# Wald's protocol — synthetic LR generated by degrading real Sentinel-2 HR; no external HR reference used.

import os
import glob
import numpy as np
import rasterio
from rasterio.enums import Resampling
import torch
from torch.utils.data import Dataset
import torchvision.transforms.functional as TF


class Sentinel2WaldDataset(Dataset):
    def __init__(
        self,
        hr_dir="datasets/samples/train/hr",
        lr_dir="datasets/samples/train/lr",
        hr_size=256,
        lr_size=64,
        scale=4,
        blur_kernel_size=5,
        blur_sigma=1.2,
        auto_generate_lr=True
    ):
        super().__init__()
        self.hr_dir = hr_dir
        self.lr_dir = lr_dir
        self.hr_size = hr_size
        self.lr_size = lr_size
        self.scale = scale
        self.blur_kernel_size = blur_kernel_size
        self.blur_sigma = blur_sigma

        os.makedirs(self.hr_dir, exist_ok=True)
        os.makedirs(self.lr_dir, exist_ok=True)

        self.hr_files = sorted(
            glob.glob(os.path.join(self.hr_dir, "*.tif"))
            + glob.glob(os.path.join(self.hr_dir, "*.tiff"))
        )

        if auto_generate_lr and len(self.hr_files) > 0:
            self._ensure_lr_cached()

        self.lr_files = sorted(
            glob.glob(os.path.join(self.lr_dir, "*.tif"))
            + glob.glob(os.path.join(self.lr_dir, "*.tiff"))
        )

    def _ensure_lr_cached(self):
        for hr_path in self.hr_files:
            filename = os.path.basename(hr_path)
            lr_path = os.path.join(self.lr_dir, filename)
            if not os.path.exists(lr_path):
                self._generate_and_save_lr(hr_path, lr_path)

    def _generate_and_save_lr(self, hr_path, lr_path):
        with rasterio.open(hr_path) as src:
            hr_data = src.read()
            profile = src.profile.copy()

        hr_tensor = torch.from_numpy(hr_data.astype(np.float32))
        blurred = TF.gaussian_blur(
            hr_tensor,
            kernel_size=[self.blur_kernel_size, self.blur_kernel_size],
            sigma=[self.blur_sigma, self.blur_sigma]
        )

        lr_tensor = TF.resize(
            blurred,
            size=[self.lr_size, self.lr_size],
            interpolation=TF.InterpolationMode.BICUBIC,
            antialias=True
        )

        lr_data = lr_tensor.numpy()
        if hr_data.dtype == np.uint16:
            lr_data = np.clip(lr_data, 0, 65535).astype(np.uint16)
        elif hr_data.dtype == np.uint8:
            lr_data = np.clip(lr_data, 0, 255).astype(np.uint8)
        else:
            lr_data = lr_data.astype(np.float32)

        transform = profile.get("transform")
        if transform is not None:
            new_transform = transform * transform.scale(
                src.width / self.lr_size,
                src.height / self.lr_size
            )
            profile.update(transform=new_transform)

        profile.update(
            width=self.lr_size,
            height=self.lr_size,
            count=hr_data.shape[0],
            dtype=lr_data.dtype
        )

        with rasterio.open(lr_path, "w", **profile) as dst:
            dst.write(lr_data)

    def _normalize(self, data):
        data = data.astype(np.float32)
        max_val = np.max(data)
        if max_val > 1.0:
            if max_val > 255.0:
                data = np.clip(data / 10000.0, 0.0, 1.0)
            else:
                data = np.clip(data / 255.0, 0.0, 1.0)
        return np.clip(data, 0.0, 1.0)

    def __len__(self):
        return max(len(self.hr_files), 1)

    def __getitem__(self, idx):
        if len(self.hr_files) == 0:
            synthetic_hr = torch.rand(4, self.hr_size, self.hr_size, dtype=torch.float32)
            synthetic_lr = TF.resize(
                TF.gaussian_blur(synthetic_hr, [self.blur_kernel_size, self.blur_kernel_size], [self.blur_sigma, self.blur_sigma]),
                [self.lr_size, self.lr_size],
                interpolation=TF.InterpolationMode.BICUBIC,
                antialias=True
            )
            return {
                "lr": synthetic_lr,
                "hr": synthetic_hr,
                "filename": f"synthetic_{idx}.tif"
            }

        hr_path = self.hr_files[idx]
        filename = os.path.basename(hr_path)
        lr_path = os.path.join(self.lr_dir, filename)

        with rasterio.open(hr_path) as src:
            hr_data = src.read()
        hr_data = self._normalize(hr_data)
        hr_tensor = torch.from_numpy(hr_data[:4, :, :]).float()

        if os.path.exists(lr_path):
            with rasterio.open(lr_path) as src:
                lr_data = src.read()
            lr_data = self._normalize(lr_data)
            lr_tensor = torch.from_numpy(lr_data[:4, :, :]).float()
        else:
            blurred = TF.gaussian_blur(
                hr_tensor,
                kernel_size=[self.blur_kernel_size, self.blur_kernel_size],
                sigma=[self.blur_sigma, self.blur_sigma]
            )
            lr_tensor = TF.resize(
                blurred,
                size=[self.lr_size, self.lr_size],
                interpolation=TF.InterpolationMode.BICUBIC,
                antialias=True
            )

        if hr_tensor.shape[1] != self.hr_size or hr_tensor.shape[2] != self.hr_size:
            hr_tensor = TF.resize(hr_tensor, [self.hr_size, self.hr_size], antialias=True)
        if lr_tensor.shape[1] != self.lr_size or lr_tensor.shape[2] != self.lr_size:
            lr_tensor = TF.resize(lr_tensor, [self.lr_size, self.lr_size], antialias=True)

        return {
            "lr": lr_tensor,
            "hr": hr_tensor,
            "filename": filename
        }
